 "content": "def transform(grid):
    """Color the blank tail to the right of each partial horizontal mark."""
    if not grid:
        return []
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    for r, row in enumerate(grid):
        marked = [c for c, value in enumerate(row) if value != background]
        if marked:
            end = max(marked)
            for c in range(end + 1, len(row)):
                out[r][c] = 1
    return out


